insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('choose_master.v1', 'choose_master', 20, 'Quest', 'quest', false, true, '{"text":"Connect with a Master: Each Master offers a different path, with different quests and benefits. You have {firstActivePassiveTime} to choose a Master and get your first quest. Beyond that timing your account will be deleted automatically. Click on a Master below to link to their game.","component":"master_choices"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('create_account.v1', 'guest', 40, 'Quest', 'quest', false, true, '{"text":"Unlock Level 2: burn Karma faster and try to get enlightened in this life, save your progress and connect directly with a Master.","action":"signup","actionLabel":"Accept"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('karma_master.v1', 'guest', 20, 'Notification', 'notification', true, true, '{"component":"karma_master"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('level_four_permanent.v1', 'linked_master', 12, 'Unlocked', 'unlocked', true, true, '{"text":"Congratulations! You have been granted a permanent account linked to {masterName}.  You now have the ability to make your account visible for others to play your game! Go to your account to enable it.","level":4,"occurrence":"level"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('level_four_unlocked.v1', 'linked_master', 10, 'Unlocked', 'unlocked', true, true, '{"text":"Congratulations! You have unlocked Level 4! You have access to a new skill {skillFourName} and burned 1 more year of Karma!","level":4,"occurrence":"level"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('level_three_game.v1', 'linked_master', 12, 'Unlocked', 'unlocked', true, true, '{"text":"You can now create your own game and skills in the Skills section of your account panel, and become a Master in your turn.","level":3,"occurrence":"level"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('level_three_prepare.v1', 'linked_master', 15, 'Quest', 'quest', false, true, '{"text":["Before beginning this Quest you must have checked the resources of the {skillTwoName} skill. Check its description below to access it.","Only after that, click on Accept and the Quest will begin.","In the meantime practice {skillTwoName} if you don''t want to lose your account."],"level":3,"action":"accept_quest","occurrence":"level","actionLabel":"Accept"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('level_three_unlocked.v1', 'linked_master', 10, 'Unlocked', 'unlocked', true, true, '{"text":"Congratulations! You have unlocked Level 3! You have access to a new skill {skillThreeName} and burned 1 more year of Karma!","level":3,"occurrence":"level"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('level_two_map.v1', 'linked_master', 12, 'Unlocked', 'unlocked', true, true, '{"text":"You can now modify your Health and Manna bars in the Map section of your account panel.","level":2,"occurrence":"level"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('level_two_prepare.v1', 'linked_master', 15, 'Quest', 'quest', false, true, '{"text":["Before beginning this Quest you must have checked the resources of {passiveSkillName} and {skillOneName} skills. Check their description below to access it.","Only after that, click on Accept and the Quest will begin.","In the meantime practice {skillOneName} if you don''t want to lose your account."],"level":2,"action":"accept_quest","occurrence":"level","actionLabel":"Accept"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('level_two_unlocked.v1', 'linked_master', 10, 'Unlocked', 'unlocked', true, true, '{"text":"Congratulations! You have unlocked Level 2! You have accessed to a new skill {skillTwoName} and burned 1 more year of Karma!","level":2,"occurrence":"level"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('master_linked.v1', 'linked_master', 20, 'Quest', 'quest', false, true, '{"component":"linked_quest"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('masters_present.v1', 'guest', 10, 'Notification', 'notification', true, true, '{"component":"masters"}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('prayer_learned.v1', 'account', 10, 'Unlocked', 'unlocked', true, true, '{"text":"Congratulations! You have learned to pray! You can now save your progress and connect with a Master to continue to play. Click on the top right icon to add your informations."}'::jsonb);
insert into public.notifications ("id", "stage", "position", "title", "tone", "dismissible", "enabled", "content") values ('prayer_level.v1', 'guest', 30, 'Unlocked', 'unlocked', true, true, '{"text":"Congratulations! You have unlocked level 1. It has been calculated by the great Masters of this game that it takes approximately {lifeMaxYears} years for an average Human being to burn all his Karma and leave the Earth. Your prayer has burned {prayerKarmaYears} years of Karma. You have more than {remainingKarmaYears} years left."}'::jsonb);
